    private static final int MOD = 998244353;
    private static final int ROOT = 15311432;
    private static final int INVROOT = 469870224;

    private static int reverseBits(int n, int k) {
        return Integer.reverse(n) >>> (32 - k);
    }

    private static long computeModInverse(int a) {
        return computeModPow(a, MOD - 2);
    }

    private static long computeModPow(int base, int exponent) {
        long result = 1;
        long b = base;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * b) % MOD;
            }
            b = (b * b) % MOD;
            exponent >>= 1;
        }
        return result;
    }

    private static void performFFT(long[] array, int logN, boolean inverse) {
        int baseRoot = inverse ? INVROOT : ROOT;
        long root = computeModPow(baseRoot, (int) Math.pow(2, 23 - logN));
        long[] roots = new long[logN];
        roots[logN - 1] = root;
        for (int i = logN - 1; i > 0; i--) {
            roots[i - 1] = (roots[i] * roots[i]) % MOD;
        }
        for (int s = 0; s < logN; s++) {
            int segmentSize = 1 << s;
            for (int startIdx = 0; startIdx < array.length; startIdx += 2 * segmentSize) {
                long currentRoot = 1;
                for (int j = startIdx; j < startIdx + segmentSize; j++) {
                    long t = (currentRoot * array[j + segmentSize]) % MOD;
