            logSize++;
        }
        long[] array = new long[size];
        for (int num : nums) {
            array[reverseBits(num, logSize)] = 1;
        }
        performFFT(array, logSize, false);
        for (int i = 0; i < size; i++) {
            array[i] = computeModPow((int) array[i], n);
        }
        long[] tempArray = new long[size];
        for (int i = 0; i < size; i++) {
