#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;
const int ROOT = 15311432;
const int INVROOT = 469870224;

int reverseBits(int n, int k) {
    int res = 0;
    for (int i = 0; i < k; i++) {
        res = (res << 1) | (n & 1);
        n >>= 1;
    }
    return res;
}

long long computeModInverse(int a) {
    long long result = 1, base = a, exp = MOD - 2;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

long long computeModPow(long long base, long long exponent) {
    long long result = 1;
    long long b = base;
    while (exponent > 0) {
        if (exponent & 1) result = (result * b) % MOD;
        b = (b * b) % MOD;
        exponent >>= 1;
    }
    return result;
}

void performFFT(std::vector<long long>& array, int logN, bool inverse) {
    int baseRoot = inverse ? INVROOT : ROOT;
    long long root = computeModPow(baseRoot, (long long)pow(2, 23 - logN));
    std::vector<long long> roots(logN);
    roots[logN - 1] = root;
    for (int i = logN - 1; i > 0; i--) {
        roots[i - 1] = (roots[i] * roots[i]) % MOD;
    }
    for (int s = 0; s < logN; s++) {
        int segmentSize = 1 << s;
        for (int startIdx = 0; startIdx < (int)array.size(); startIdx += 2 * segmentSize) {
            long long currentRoot = 1;
            for (int j = startIdx; j < startIdx + segmentSize; j++) {
                long long t = (currentRoot * array[j + segmentSize]) % MOD;
                long long u = array[j];
                array[j] = (u + t) % MOD;
                array[j + segmentSize] = (u - t + MOD) % MOD;
                currentRoot = (roots[s] * currentRoot) % MOD;
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n_input, m;
    cin >> n_input >> m;
    int n = n_input / 2;
    vector<int> nums(m);
    for (int i = 0; i < m; i++) {
        cin >> nums[i];
    }
    std::sort(nums.begin(), nums.end());
    int minSize = n * nums[m - 1] + 2;
    int logSize = 0;
    int size = 1;
    while (size < minSize) {
        size <<= 1;
        logSize++;
    }
    vector<long long> array(size, 0);
    for (int num : nums) {
        array[reverseBits(num, logSize)] = 1;
    }
    performFFT(array, logSize, false);
    for (int i = 0; i < size; i++) {
        array[i] = computeModPow(array[i], n);
    }
    vector<long long> tempArray(size, 0);
    for (int i = 0; i < size; i++) {
        tempArray[reverseBits(i, logSize)] = array[i] % MOD;
    }
    array = tempArray;
    performFFT(array, logSize, true);
    long long totalSumSquares = 0;
    for (int i = 0; i < size; i++) {
        totalSumSquares = (totalSumSquares + (array[i] * array[i]) % MOD) % MOD;
    }
    long long invSize = computeModInverse(size);
    long long result = ((totalSumSquares % MOD) * (invSize % MOD)) % MOD;
    result = (result * invSize) % MOD;
    cout << result << "\n";
    return 0;
}

